 func TestGetAssociatedCommits(t *testing.T) {
 	tmpDir := t.TempDir()
 	t.Chdir(tmpDir)

 	// Initialize git repo
 	repo, err := git.PlainInit(tmpDir, false)
 	if err != nil {
 		t.Fatalf("failed to init git repo: %v", err)
 	}

 	w, err := repo.Worktree()
 	if err != nil {
