 		AuthorEmail:  "test@example.com",
 	})
 	if err != nil {
 		t.Fatalf("WriteCommitted() error = %v", err)
 	}

 	// Verify no summary initially (summary is stored in session-level metadata)
 	metadata := readLatestSessionMetadata(t, repo, checkpointID)
